package vn.rtr.aeris.native94;
import java.nio.file.*;import java.nio.charset.StandardCharsets;
public final class CompositeTest87{public static void main(String[]args)throws Exception{Workspaces w=new Workspaces(Paths.get(args[0]));w.store().save("ROOT","base".getBytes(StandardCharsets.UTF_8));w.sitl().save("ROOT","review1".getBytes(StandardCharsets.UTF_8));byte[]a=w.archive();w.exported(a,a);DraftStore.Snapshot old=w.sitl().load();w.sitl().save(old.token,"review2".getBytes(StandardCharsets.UTF_8));boolean denied=false;try{w.fresh();}catch(java.io.IOException e){denied=true;}if(!denied)throw new AssertionError("SITL change must invalidate export");System.out.println("PASS SITL head mutation blocks fresh despite unchanged mock HEAD");denied=false;try{w.exported(a,a);}catch(java.io.IOException e){denied=true;}if(!denied)throw new AssertionError("Old archive must not authorize current SITL HEAD");System.out.println("PASS old archive cannot authorize changed SITL head");byte[]b=w.archive();w.exported(b,b);String previous=w.id();w.fresh();if(w.id().equals(previous))throw new AssertionError("fresh");if(!Files.isDirectory(Paths.get(args[0]).resolve(previous)))throw new AssertionError("old retained");System.out.println("PASS exact composite export allows explicit fresh and retains original");}}
